//////////////////////////////////////////////INTERFACE//////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////////////////////////

(
input logic clk                   ,
input           rst               ,
input logic data_in           ,
input logic push                  ,
input logic pop                   ,
input logic empty                  ,
input logic full                   ,
input logic data_out           ,
input logic [DEPTH_W-1:0]          size,
input logic                        error
