   ////////////////////////////////////////////////////////////////////////////////////////////////////
   ////////////////////////////////////////////////CLK////////////////////////////////////////////////
   ////////////////////////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////////////////////////
   ////////////////////////////////////////////////ENV/////////////////////////////////////////////////
   ////////////////////////////////////////////////////////////////////////////////////////////////////

   logic [DEPTH_W-1:0] fifo_size;
   always_ff @(posedge clk) begin

      if(rst) fifo_size = '0; 
      else begin
